alter table if exists public.knowledge_documents
    drop constraint if exists knowledge_documents_source_type_check;

alter table if exists public.knowledge_documents
    add constraint knowledge_documents_source_type_check
    check (source_type in ('public_page', 'site_function', 'resource_doc', 'internal_sales_kb', 'faq', 'datasheet', 'case_study', 'certification'));

