upsert_docs as (
    insert into public.knowledge_documents (
        source_type,
        visibility,
        language,
        title,
        canonical_url,
        excerpt,
        content_markdown,
        source_meta,
        status,
        last_crawled_at
    )
    select
        'site_function',
        'public',
        'en',
        seed.title,
        seed.canonical_url,
        seed.excerpt,
        '# ' || seed.title || E'\n\n' || seed.chunk_text,
        jsonb_build_object(
            'seed', 'public_site_feature_directory_v1',
            'kind', 'site_function',
            'feature_group', seed.feature_group,
            'feature_id', seed.feature_id,
            'path', seed.path,
            'link_label', seed.link_label,
            'recommendation_hint', seed.recommendation_hint
        ),
        'published',
        timezone('utc', now())
    from seed
    on conflict (canonical_url) do update
    set
        source_meta = coalesce(public.knowledge_documents.source_meta, '{}'::jsonb) || excluded.source_meta,
        last_crawled_at = timezone('utc', now()),
        updated_at = timezone('utc', now())
    returning canonical_url
)
select count(*) from upsert_docs;

delete from public.knowledge_chunks
where source_meta ->> 'seed' = 'public_site_feature_directory_v1';

