insert into public.knowledge_chunks (
    document_id,
    chunk_text,
    chunk_summary,
    language,
    keywords,
    section_path,
    sort_order,
    token_count,
    source_meta,
    search_text
)
select
    kd.id,
    seed.chunk_text,
    seed.chunk_summary,
    'en',
    seed.keywords,
    seed.section_path,
    seed.sort_order,
    seed.token_count,
    jsonb_build_object(
        'seed', 'public_site_feature_directory_v1',
        'kind', 'site_function',
        'feature_group', seed.feature_group,
        'feature_id', seed.feature_id,
        'path', seed.path,
        'link_label', seed.link_label,
        'recommendation_hint', seed.recommendation_hint
    ),
    seed.chunk_text || ' ' || seed.chunk_summary || ' ' || array_to_string(seed.keywords, ' ')
from seed
join public.knowledge_documents kd
    on kd.canonical_url = seed.canonical_url
where kd.status = 'published';
